css:
/* ==========================================================================
   Sun State — site-wide corrections to the block library.
   Everything here is a token consequence, not a one-off colour: the brand
   accent is school-bus yellow, and yellow cannot carry text on a light
   background. The handoff answers this with a second accent value — "accent
   as text", #8A6D00 — which is tokens.colors.accentDark. So every place the
   platform paints --accent on paper switches to --accent-dark, and every
   place it paints on ink keeps --accent.
   ========================================================================== */

.bz-eyebrow { font-family: var(--font-body); letter-spacing: .12em; color: var(--accent-dark); }
.bz-section--bg-ink .bz-eyebrow,
.bz-col--bg-ink .bz-eyebrow,
.bz-block--hero .bz-eyebrow,
.bz-block--statBand .bz-eyebrow { color: var(--accent); }

.bz-btn--link { color: var(--accent-dark); }
.bz-section--bg-ink .bz-btn--link,
.bz-col--bg-ink .bz-btn--link,
.bz-btn--on-dark.bz-btn--link { color: var(--accent); }

.bz-text a, .bz-block p a { color: var(--accent-dark); text-decoration: underline; text-underline-offset: 3px; }
.bz-section--bg-ink .bz-text a,
.bz-col--bg-ink .bz-text a { color: var(--accent); }

.bz-block a:focus-visible,
.bz-block button:focus-visible,
.bz-block summary:focus-visible,
.bz-input:focus-visible { outline-color: var(--accent-dark); }
.bz-section--bg-ink a:focus-visible,
.bz-section--bg-ink button:focus-visible,
.bz-col--bg-ink a:focus-visible { outline-color: var(--accent); }

/* A block dropped in a column is already inside the section's container, so
   its own container must not add a second gutter or a second max-width. */
.bz-col .bz-container { max-width: none; padding-inline: 0; }

/* Display type: the handoff runs INTL Headline at 700 with neutral tracking. */
.bz-block h1, .bz-block h2 { font-weight: 700; letter-spacing: 0; }
.bz-block h3 { letter-spacing: .01em; }

/* Body copy sits at the handoff's ink-700 rather than full ink. */
.bz-text p { color: #3A342C; line-height: 1.7; }
.bz-section--bg-ink .bz-text p,
.bz-col--bg-ink .bz-text p { color: #D8D2C4; }

/* Cards and inputs pick up the handoff's radii and hairline. */
.bz-card { border-radius: var(--radius-card); overflow: hidden; }
.bz-form { max-width: 440px; }

/* The handoff runs navigation and neutral buttons in INTL Text; INTL Headline
   is a caps display face and is reserved for headings and solid CTAs. */
.bz-navitem > a { font-family: var(--font-body); font-weight: 600; }
.bz-btn { min-height: 46px; }
.bz-btn--secondary, .bz-btn--link { font-family: var(--font-body); font-weight: 600; }
.bz-label { font-family: var(--font-body); }

/* A form block that already sits under its own heading should not repeat it. */
.bz-formblock > h2 + .bz-form .bz-form__t,
.bz-formblock > h3 + .bz-form .bz-form__t { display: none; }


/* A stacked row keeps its twelve column tracks, and each track still carries
   the row's column gap — eleven gaps of 48px do not fit on a phone, so every
   track collapses to 0 and the full-width column ends up wider than its
   container. Once the columns are stacked only the row gap means anything, so
   the column gap goes. (Reported upstream: .bz-row should do this itself.) */
@media (max-width: 640px) {
  .bz-row--stack-tablet,
  .bz-row--stack-mobile { column-gap: 0; row-gap: var(--bz-gap, var(--space-6)); }
}
@media (min-width: 641px) and (max-width: 1100px) {
  .bz-row--stack-tablet { column-gap: 0; row-gap: var(--bz-gap, var(--space-6)); }
}
